    out=set()
    for a in P:
        for b in Q:
            s=(a[0]+b[0],a[1]+b[1]); out^={s}
    return frozenset(out)
def divide(P,Q):
    """exact division of polynomials (nonneg exponents) over GF2; returns quotient or None"""
    P=set(P); Q=sorted(Q)  # lex order by (i,j)
    lead=max(Q)
    quo=set()
