    D=[sympy.Poly(0,T,modulus=2), sympy.Poly(T,T,modulus=2), sympy.Poly(T**2,T,modulus=2)]
    for e in range(3,m): D.append(sympy.Poly(T,T,modulus=2)*D[-1]+D[-2])
    # Psi-ish: t_1 is a root of D_m(t) / t ... take z^-((m-1)/2) Phi_m? use D_m(t) = t * prod Psi^2;
    # minimal polynomial of t_1: factor of (1 + sum_{e=1}^{(m-1)/2} D_e) for prime m; general: factor D_m(t)/t
    # and pick a factor whose root has the right order: test via t_j distinctness
    P=sympy.Poly(1,T,modulus=2)
    for e in range(1,(m+1)//2): P=P+D[e]   # = z^{-(m-1)/2}(1+z+...+z^{m-1}) in t
    for g,_ in P.factor_list()[1]:
        if g.degree()==sord(m):
