        for _ in range(s):
            R^=np.where(B&1,A,0); B>>=1; A<<=1
            A^=np.where((A>>s)&1,self.mod,0)
        return R
    def vpow(self,A,e):
        R=np.ones_like(A); 
        while e:
            if e&1: R=self.vmul(R,A)
            A=self.vmul(A,A); e>>=1
        return R

